<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Dune Line — Sleep in the Desert. Wake in Neon.</title>
<meta name="description" content="Dune Line is a fictional overnight train crossing the desert from Aurelia Sands to Vesper City.">
<style>
  :root{
    --night:#0c0e26;
    --night-2:#151839;
    --night-3:#211647;
    --plum:#2d1b4e;
    --cream:#fff7e9;
    --paper:#fffdf7;
    --warm:#fdf0dc;
    --sand:#e9c48f;
    --sand-2:#d99a5c;
    --sand-3:#b96f3f;
    --ink:#1b172f;
    --muted:#716a83;
    --muted-light:#b9b4d6;
    --cyan:#5eead4;
    --pink:#ff6ab5;
    --violet:#8b7cf6;
    --line:rgba(27,23,47,.11);
    --line-light:rgba(255,255,255,.13);
    --shadow:0 24px 60px rgba(21,15,52,.16);
    --shadow-sm:0 10px 30px rgba(21,15,52,.10);
    --radius:24px;
    --font-sans: ui-sans-system, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --font-serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Times New Roman", serif;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    font-family:var(--font-sans);
    background:var(--cream);
    color:var(--ink);
    line-height:1.6;
    -webkit-font-smoothing:antialiased;
    overflow-x:hidden;
  }
  ::selection{background:var(--pink);color:white}
  a{color:inherit;text-decoration:none}
  button{font:inherit;cursor:pointer}
  :focus-visible{outline:3px solid var(--cyan);outline-offset:3px;border-radius:6px}
  .wrap{width:min(1180px,calc(100% - 48px));margin:0 auto}
  .eyebrow{
    display:inline-flex;align-items:center;gap:10px;
    font-size:.72rem;font-weight:800;letter-spacing:.22em;text-transform:uppercase;
  }
  .eyebrow::before{content:"";width:28px;height:1px;background:currentColor;opacity:.7}
  .btn{
    display:inline-flex;align-items:center;justify-content:center;gap:9px;
    padding:14px 24px;border-radius:999px;border:1px solid transparent;
    font-weight:750;font-size:.95rem;line-height:1;transition:.25s ease;white-space:nowrap;
  }
  .btn-sand{background:var(--sand);color:#241331;box-shadow:0 12px 28px rgba(233,196,143,.28)}
  .btn-sand:hover{background:#f4d6a7;transform:translateY(-2px)}
  .btn-ghost{background:rgba(255,255,255,.06);color:#fff;border-color:rgba(255,255,255,.22);backdrop-filter:blur(8px)}
  .btn-ghost:hover{background:rgba(255,255,255,.13);transform:translateY(-2px)}
  .btn-dark{background:var(--night);color:#fff}
  .btn-dark:hover{background:var(--night-3);transform:translateY(-2px)}
  .btn-outline{background:transparent;color:var(--ink);border-color:var(--line)}
  .btn-outline:hover{border-color:var(--ink)}
  .reveal{opacity:0;transform:translateY(22px);transition:opacity .7s ease,transform .7s ease}
  .reveal.in{opacity:1;transform:none}

  /* ---------- NAV ---------- */
  header{
    position:fixed;inset:0 0 auto 0;z-index:50;
    background:rgba(12,14,38,.78);
    backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);
    border-bottom:1px solid rgba(255,255,255,.09);
  }
  .nav{height:72px;display:flex;align-items:center;justify-content:space-between;gap:24px}
  .logo{display:flex;align-items:center;gap:11px;color:#fff;font-weight:850;letter-spacing:.02em;font-size:1.08rem}
  .logo-mark{
    width:38px;height:38px;border-radius:11px;display:grid;place-items:center;flex:none;
    background:linear-gradient(145deg,var(--sand),#c97e46);
    box-shadow:0 8px 20px rgba(217,154,92,.35);
  }
  .logo small{display:block;font-size:.58rem;letter-spacing:.28em;text-transform:uppercase;color:var(--sand);font-weight:800;line-height:1;margin-top:2px}
  .nav-links{display:flex;align-items:center;gap:34px;color:#d8d4ef;font-size:.92rem;font-weight:600}
  .nav-links a{position:relative;padding:6px 0}
  .nav-links a::after{content:"";position:absolute;left:0;bottom:0;width:0;height:2px;background:linear-gradient(90deg,var(--cyan),var(--pink));transition:.25s}
  .nav-links a:hover{color:#fff}
  .nav-links a:hover::after{width:100%}
  .nav-cta{display:flex;align-items:center;gap:12px}
  .nav-book{padding:11px 20px;font-size:.88rem}
  .burger{display:none;background:none;border:0;width:42px;height:42px;border-radius:10px;place-items:center}
  .burger span{display:block;width:22px;height:2px;background:#fff;margin:5px auto;border-radius:2px;transition:.25s}

  /* ---------- HERO ---------- */
  .hero{
    position:relative;color:#fff;overflow:hidden;
    background:
      radial-gradient(900px 480px at 85% -10%, rgba(139,124,246,.38), transparent 60%),
      radial-gradient(700px 420px at 8% 18%, rgba(255,106,181,.16), transparent 60%),
      linear-gradient(180deg,#090b22 0%,#14163a 46%,#33204f 76%,#593052 100%);
    padding:158px 0 0;
  }
  .stars,.stars::before,.stars::after{
    content:"";position:absolute;inset:0;pointer-events:none;
    background-image:
      radial-gradient(1.5px 1.5px at 12% 22%, #fff 50%, transparent 51%),
      radial-gradient(1px 1px at 28% 12%, #ffe9c4 50%, transparent 51%),
      radial-gradient(1.5px 1.5px at 46% 30%, #fff 50%, transparent 51%),
      radial-gradient(1px 1px at 63% 14%, #bffcf3 50%, transparent 51%),
      radial-gradient(1.5px 1.5px at 78% 26%, #fff 50%, transparent 51%),
      radial-gradient(1px 1px at 90% 10%, #ffd6ec 50%, transparent 51%),
      radial-gradient(1px 1px at 36% 42%, #fff 50%, transparent 51%),
      radial-gradient(1px 1px at 70% 44%, #ffe9c4 50%, transparent 51%);
    animation:twinkle 4.5s ease-in-out infinite alternate;
  }
  .stars::before{transform:translate(38px,26px) scale(1.15);opacity:.55;animation-delay:1.2s}
  .stars::after{transform:translate(-52px,12px) scale(.9);opacity:.4;animation-delay:2.1s}
  @keyframes twinkle{from{opacity:.55}to{opacity:1}}
  .hero-grid{position:relative;z-index:2;display:grid;grid-template-columns:1.02fr .98fr;gap:58px;align-items:center;padding-bottom:64px}
  .hero .eyebrow{color:var(--sand)}
  h1{
    font-family:var(--font-serif);font-weight:500;
    font-size:clamp(3rem,5.6vw,4.85rem);line-height:.98;letter-spacing:-.02em;
    margin:22px 0 22px;max-width:10.5ch;
  }
  h1 em{font-style:italic;background:linear-gradient(92deg,var(--cyan) 5%,#a5b4fc 48%,var(--pink) 95%);-webkit-background-clip:text;background-clip:text;color:transparent}
  h1 .sand-word{color:var(--sand)}
  .hero-sub{font-size:1.13rem;line-height:1.7;color:#dcd8f2;max-width:54ch}
  .hero-actions{display:flex;flex-wrap:wrap;gap:14px;margin:32px 0 34px}
  .hero-meta{display:flex;flex-wrap:wrap;gap:0;border-top:1px solid var(--line-light);padding-top:22px;max-width:560px}
  .hero-meta div{padding-right:26px;margin-right:26px;border-right:1px solid var(--line-light)}
  .hero-meta div:last-child{border:0;margin:0;padding:0}
  .hero-meta b{display:block;font-family:var(--font-serif);font-size:1.45rem;font-weight:600;line-height:1.1;color:#fff}
  .hero-meta span{font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;color:var(--muted-light);font-weight:700}

  /* Scene card */
  .scene-card{
    background:linear-gradient(180deg,rgba(255,255,255,.10),rgba(255,255,255,.045));
    border:1px solid rgba(255,255,255,.16);border-radius:28px;padding:14px;
    box-shadow:0 34px 80px rgba(0,0,0,.38);backdrop-filter:blur(10px);
  }
  .scene{border-radius:19px;overflow:hidden;line-height:0;background:#101336}
  .scene svg{width:100%;height:auto;display:block}
  .train-bob{animation:bob 4.6s ease-in-out infinite}
  @keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-2.5px)}}
  .flicker{animation:flick 3.4s ease-in-out infinite}
  @keyframes flick{0%,100%{opacity:1}48%{opacity:.72}52%{opacity:1}78%{opacity:.84}}
  .scene-caption{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 6px 6px}
  .scene-caption b{font-size:.95rem;display:block;line-height:1.3}
  .scene-caption span{font-size:.8rem;color:var(--muted-light)}
  .live-badge{display:inline-flex;align-items:center;gap:8px;font-size:.72rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:#bbf7ec;background:rgba(94,234,212,.12);border:1px solid rgba(94,234,212,.3);padding:8px 12px;border-radius:999px;white-space:nowrap}
  .live-badge i{width:7px;height:7px;border-radius:50%;background:var(--cyan);box-shadow:0 0 0 0 rgba(94,234,212,.6);animation:pulse 1.8s infinite}
  @keyframes pulse{to{box-shadow:0 0 0 8px rgba(94,234,212,0)}}

  /* Route strip */
  .route-strip{position:relative;z-index:2;border-top:1px solid var(--line-light);background:rgba(7,8,25,.32)}
  .route{display:flex;align-items:flex-start;justify-content:space-between;padding:26px 4px 30px;position:relative}
  .route::before{content:"";position:absolute;left:4%;right:4%;top:35px;height:1px;background:linear-gradient(90deg,var(--sand),rgba(255,255,255,.25),var(--cyan),var(--pink))}
  .route div{text-align:center;flex:1;position:relative}
  .route i{display:block;width:11px;height:11px;margin:4px auto 10px;border-radius:50%;background:var(--night);border:2px solid var(--sand);position:relative;z-index:1}
  .route div:last-child i{border-color:var(--pink);background:var(--pink);box-shadow:0 0 16px rgba(255,106,181,.8)}
  .route b{display:block;font-size:.82rem;letter-spacing:.06em}
  .route span{font-size:.7rem;letter-spacing:.14em;text-transform:uppercase;color:var(--muted-light);font-weight:700}

  /* ---------- SECTIONS ---------- */
  section{padding:104px 0}
  .section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:36px;margin-bottom:48px}
  .section-head .eyebrow{color:var(--sand-3)}
  h2{font-family:var(--font-serif);font-weight:500;font-size:clamp(2.1rem,3.6vw,3.1rem);line-height:1.06;letter-spacing:-.015em;margin-top:16px;max-width:18ch}
  h2 em{font-style:italic;color:var(--sand-3)}
  .section-head p{max-width:38ch;color:var(--muted);font-size:1.02rem}

  /* Features */
  .features{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
  .feature{
    background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);
    padding:34px 30px 30px;box-shadow:var(--shadow-sm);position:relative;overflow:hidden;transition:.3s ease;
  }
  .feature:hover{transform:translateY(-6px);box-shadow:var(--shadow)}
  .feature::after{content:"";position:absolute;inset:auto 0 0 0;height:3px;background:linear-gradient(90deg,var(--sand),var(--pink));opacity:0;transition:.3s}
  .feature:hover::after{opacity:1}
  .feature-num{position:absolute;top:22px;right:26px;font-family:var(--font-serif);font-style:italic;font-size:1rem;color:#cbb astonishing}
  .feature-num{color:#d6b48a}
  .icon{
    width:56px;height:56px;border-radius:17px;display:grid;place-items:center;margin-bottom:22px;color:#3a214f;
    background:linear-gradient(145deg,#f7dfba,#efc48d);box-shadow:inset 0 1px 0 #fff8,0 10px 20px rgba(185,111,63,.18);
  }
  .feature:nth-child(2) .icon{background:linear-gradient(145deg,#1d1f4d,#33215e);color:var(--cyan)}
  .feature:nth-child(3) .icon{background:linear-gradient(145deg,#ffe1ef,#ffc2dd);color:#8f245e}
  .feature h3{font-family:var(--font-serif);font-size:1.42rem;font-weight:600;line-height:1.2;margin-bottom:10px}
  .feature p{color:var(--muted);font-size:.97rem}
  .feature ul{list-style:none;margin-top:18px;padding-top:16px;border-top:1px dashed var(--line);display:grid;gap:8px;font-size:.88rem;font-weight:650;color:#453e5f}
  .feature li::before{content:"—";color:var(--sand-2);margin-right:9px}

  /* Timetable */
  .dark-section{background:radial-gradient(800px 400px at 90% 0%,rgba(139,124,246,.24),transparent 60%),linear-gradient(180deg,var(--night) 0%,#121331 100%);color:#fff}
  .dark-section .section-head p{color:var(--muted-light)}
  .dark-section .eyebrow{color:var(--cyan)}
  .dark-section h2 em{color:var(--cyan)}
  .table-card{background:rgba(255,255,255,.045);border:1px solid var(--line-light);border-radius:26px;overflow:hidden;box-shadow:0 30px 70px rgba(0,0,0,.3)}
  .table-scroll{overflow-x:auto}
  table{width:100%;border-collapse:collapse;min-width:820px;text-align:left}
  th{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;color:var(--muted-light);font-weight:800;padding:20px 24px;border-bottom:1px solid var(--line-light);background:rgba(255,255,255,.03)}
  td{padding:22px 24px;border-bottom:1px solid rgba(255,255,255,.07);vertical-align:middle}
  tbody tr{transition:.22s;cursor:pointer}
  tbody tr:hover{background:rgba(255,255,255,.055)}
  tbody tr:last-child td{border-bottom:0}
  tbody tr.selected{background:linear-gradient(90deg,rgba(233,196,143,.13),rgba(255,106,181,.07));box-shadow:inset 3px 0 0 var(--sand)}
  .train-no{font-weight:850;letter-spacing:.04em}
  .train-no small{display:block;color:var(--muted-light);font-weight:600;font-size:.78rem;letter-spacing:0;margin-top:2px}
  .time{font-family:var(--font-serif);font-size:1.55rem;line-height:1;color:#fff}
  .station{font-size:.86rem;color:#cfcbea;margin-top:5px}
  .arrow-cell{color:var(--sand);font-size:1.1rem}
  .duration{font-weight:700;font-size:.92rem}
  .duration small{display:block;color:var(--muted-light);font-weight:600;font-size:.78rem}
  .tag{display:inline-flex;padding:6px 10px;border-radius:999px;font-size:.7rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;border:1px solid}
  .tag-pop{color:#ffd9a8;background:rgba(233,196,143,.1);border-color:rgba(233,196,143,.35)}
  .tag-fast{color:#a7f3ea;background:rgba(94,234,212,.09);border-color:rgba(94,234,212,.32)}
  .tag-sun{color:#ffc2dd;background:rgba(255,106,181,.09);border-color:rgba(255,106,181,.32)}
  .tag-quiet{color:#c4b5fd;background:rgba(139,124,246,.1);border-color:rgba(139,124,246,.35)}
  .select-btn{background:transparent;color:#fff;border:1px solid rgba(255,255,255,.28);border-radius:999px;padding:9px 15px;font-size:.82rem;font-weight:750;transition:.22s;white-space:nowrap}
  tr.selected .select-btn,.select-btn:hover{background:var(--sand);border-color:var(--sand);color:#241331}
  .table-note{display:flex;flex-wrap:wrap;gap:10px 26px;justify-content:space-between;padding:18px 24px;color:var(--muted-light);font-size:.85rem;border-top:1px solid var(--line-light);background:rgba(0,0,0,.14)}
  .table-note b{color:#fff}

  /* Pricing */
  .toggle{display:inline-flex;background:#eee2cf;border:1px solid var(--line);padding:5px;border-radius:999px;gap:4px}
  .toggle button{border:0;background:transparent;padding:10px 18px;border-radius:999px;font-weight:750;font-size:.88rem;color:var(--muted);transition:.22s}
  .toggle button.active{background:var(--night);color:#fff;box-shadow:0 6px 16px rgba(12,14,38,.25)}
  .toggle-note{font-size:.82rem;color:var(--muted);margin-top:10px;text-align:right}
  .pricing{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;align-items:stretch}
  .plan{background:var(--paper);border:1px solid var(--line);border-radius:26px;padding:34px 30px;display:flex;flex-direction:column;box-shadow:var(--shadow-sm);transition:.3s;position:relative}
  .plan:hover{transform:translateY(-6px);box-shadow:var(--shadow)}
  .plan.popular{background:linear-gradient(165deg,#191b45,#2b174d 72%,#3c1d4e);color:#fff;border-color:rgba(255,255,255,.12);box-shadow:0 30px 65px rgba(23,16,60,.32)}
  .pop-label{position:absolute;top:-13px;left:50%;transform:translateX(-50%);background:linear-gradient(90deg,var(--cyan),var(--pink));color:#14102e;font-size:.68rem;font-weight:900;letter-spacing:.14em;text-transform:uppercase;padding:7px 13px;border-radius:999px;white-space:nowrap}
  .plan-name{font-size:.75rem;font-weight:850;letter-spacing:.2em;text-transform:uppercase;color:var(--sand-3)}
  .popular .plan-name{color:var(--cyan)}
  .plan h3{font-family:var(--font-serif);font-size:1.65rem;font-weight:600;margin:8px 0 6px}
  .plan-desc{font-size:.93rem;color:var(--muted);min-height:48px}
  .popular .plan-desc{color:#c9c4e9}
  .price{display:flex;align-items:baseline;gap:7px;margin:22px 0 4px}
  .price b{font-family:var(--font-serif);font-size:3rem;font-weight:500;line-height:1;letter-spacing:-.03em}
  .price span{color:var(--muted);font-size:.88rem;font-weight:650}
  .popular .price span{color:var(--muted-light)}
  .per-note{font-size:.8rem;color:var(--muted);margin-bottom:24px}
  .popular .per-note{color:var(--muted-light)}
  .plan ul{list-style:none;display:grid;gap:12px;padding:22px 0 26px;border-top:1px dashed var(--line);margin-bottom:auto;font-size:.93rem}
  .popular ul{border-color:rgba(255,255,255,.16)}
  .plan li{display:flex;gap:10px;align-items:flex-start}
  .plan li::before{content:"✓";flex:none;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font-size:.68rem;font-weight:900;background:#f3dfc2;color:#7c471c;margin-top:2px}
  .popular li::before{background:rgba(94,234,212,.16);color:var(--cyan)}
  .plan .btn{width:100%}
  .popular .btn{background:var(--sand);color:#241331}
  .popular .btn:hover{background:#f6d8a9}
  .plan.chosen{outline:3px solid rgba(255,106,181,.55);outline-offset:3px}

  /* Booking summary */
  .summary{
    margin-top:26px;background:var(--night);color:#fff;border-radius:22px;padding:20px 22px;
    display:flex;align-items:center;gap:22px;flex-wrap:wrap;box-shadow:0 22px 50px rgba(12,14,38,.22);
  }
  .summary-item{min-width:130px}
  .summary-item span{display:block;font-size:.66rem;letter-spacing:.17em;text-transform:uppercase;color:var(--muted-light);font-weight:800;margin-bottom:3px}
  .summary-item b{font-size:.96rem}
  .stepper{display:flex;align-items:center;gap:12px}
  .stepper button{width:34px;height:34px;border-radius:50%;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.06);color:#fff;font-size:1.1rem;line-height:1;display:grid;place-items:center}
  .stepper button:hover{background:var(--sand);color:var(--night);border-color:var(--sand)}
  .summary-total{margin-left:auto;text-align:right}
  .summary-total span{display:block;font-size:.66rem;letter-spacing:.17em;text-transform:uppercase;color:var(--muted-light);font-weight:800}
  .summary-total b{font-family:var(--font-serif);font-size:2rem;font-weight:500;line-height:1}
  .summary .btn{flex:none}

  /* Testimonial */
  .testimonial-sec{padding-top:20px}
  .testimonial{
    position:relative;overflow:hidden;border-radius:30px;padding:64px clamp(28px,6vw,76px);text-align:center;
    background:
      radial-gradient(600px 280px at 12% 0%,rgba(255,255,255,.65),transparent 60%),
      linear-gradient(135deg,#f3d5a7,#eebd8d 48%,#dda0a8);
    box-shadow:var(--shadow);
  }
  .testimonial::before{content:"“";position:absolute;top:-38px;left:34px;font-family:var(--font-serif);font-size:11rem;color:rgba(255,255,255,.34);line-height:1}
  .stars-row{color:#7c3f16;letter-spacing:.35em;font-size:.95rem;margin-bottom:22px}
  blockquote{font-family:var(--font-serif);font-size:clamp(1.65rem,3.2vw,2.55rem);line-height:1.28;font-weight:500;letter-spacing:-.01em;max-width:900px;margin:0 auto;color:#2a1836}
  blockquote em{font-style:italic;color:#7c2458}
  .person{display:flex;align-items:center;justify-content:center;gap:14px;margin-top:30px;text-align:left}
  .avatar{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:var(--night);color:var(--sand);font-family:var(--font-serif);font-weight:700;border:2px solid rgba(255,255,255,.7);box-shadow:var(--shadow-sm)}
  .person b{display:block;line-height:1.25;color:#2a1836}
  .person span{font-size:.86rem;color:#6d4356}

  /* Final CTA */
  .cta{margin:0 0 104px;border-radius:30px;padding:58px clamp(28px,5vw,64px);color:#fff;position:relative;overflow:hidden;background:linear-gradient(120deg,#12143a,#2c1850 58%,#57284f);display:flex;align-items:center;justify-content:space-between;gap:34px;flex-wrap:wrap;box-shadow:var(--shadow)}
  .cta::after{content:"";position:absolute;width:420px;height:420px;border-radius:50%;right:-140px;top:-190px;background:radial-gradient(circle,rgba(255,106,181,.38),transparent 65%)}
  .cta h2{color:#fff;margin:0;max-width:15ch;position:relative;z-index:1}
  .cta p{color:#cfcbea;margin-top:12px;max-width:48ch;position:relative;z-index:1}
  .cta .btn{position:relative;z-index:1}

  /* Footer */
  footer{background:#080a20;color:#bdb9d9;padding:72px 0 30px}
