      passengerEl=document.getElementById('passengerCount');

  function money(n){return '$'+n.toLocaleString('en-US');}
  function updateSummary(){
    sumDeparture.textContent=state.departure;
    sumPlan.textContent=state.plan;
    passengerEl.textContent=state.passengers;
    sumTotal.textContent=money(state.price*state.passengers);
  }

  // Timetable selection
  var rows=document.querySelectorAll('#departureRows tr');
  function selectRow(row){
    rows.forEach(function(r){
      r.classList.remove('selected');
      r.querySelector('.select-btn').textContent='Select';
    });
    row.classList.add('selected');
    row.querySelector('.select-btn').textContent='Selected';
    state.departure=row.getAttribute('data-departure');
    updateSummary();
  }
  rows.forEach(function(row){
    row.addEventListener('click',function(){selectRow(row);});
    row.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRow(row);}});
  });

  // Pricing
  var plans=document.querySelectorAll('.plan'),
      btnOne=document.getElementById('btnOneWay'),
      btnRet=document.getElementById('btnReturn');

  function refreshPrices(){
    plans.forEach(function(card){
      var val=state.returnTrip?card.getAttribute('data-return'):card.getAttribute('data-oneway');
      card.querySelector('.price-val').textContent=val;
      card.querySelector('.price-per').textContent=state.returnTrip?'/ return':'/ one way';
      if(card.getAttribute('data-plan')===state.plan){state.price=parseInt(val,10);}
    });
    updateSummary();
  }
  btnOne.addEventListener('click',function(){state.returnTrip=false;btnOne.classList.add('active');btnRet.classList.remove('active');refreshPrices();});
