  plans.forEach(function(card){
    card.querySelector('.choose-plan').addEventListener('click',function(){
      plans.forEach(function(c){
        c.classList.remove('chosen');
        var b=c.querySelector('.choose-plan');
        b.textContent='Choose '+c.getAttribute('data-plan');
      });
      card.classList.add('chosen');
      state.plan=card.getAttribute('data-plan');
      state.price=parseInt(state.returnTrip?card.getAttribute('data-return'):card.getAttribute('data-oneway'),10);
      card.querySelector('.choose-plan').textContent='Chosen ✓';
      updateSummary();
      document.querySelector('.summary').scrollIntoView({behavior:'smooth',block:'center'});
    });
  });

  // Passengers
  document.getElementById('minusBtn').addEventListener('click',function(){
    if(state.passengers>1){state.passengers--;updateSummary();}
  });
  document.getElementById('plusBtn').addEventListener('click',function(){
    if(state.passengers<6){state.passengers++;updateSummary();}
  });

  // Reserve / toast
  var toast=document.getElementById('toast'),toastText=document.getElementById('toastText'),timer;
  document.getElementById('reserveBtn').addEventListener('click',function(){
    toastText.textContent=state.departure+' · '+state.plan+' for '+state.passengers+
      (state.passengers===1?' passenger':' passengers')+' — '+money(state.price*state.passengers)+
      (state.returnTrip?' (return)':'')+'. See you at Platform 3.';
    toast.classList.add('show');
    clearTimeout(timer);
    timer=setTimeout(function(){toast.classList.remove('show');},5200);
  });

  // Reveal on scroll
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(entries){
      entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});
    },{threshold:.12});
    document.querySelectorAll('.reveal').forEach(function(el){io.observe(el);});
  }else{
    document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('in');});
  }

  document.getElementById('year').textContent=new Date().getFullYear();
  updateSummary();
})();
</script>
</body>
